insert into cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-honors-anchored-rows-s654','decision','Honors step 2 rows rest on same-college anchors','S654 conductor, #3315 a8563faf: each honors_of row rests on anchors (an Honors and a base course, one college, same subject and number, plus a course title signal); a row needs every anchor in one base; a mint also needs every member anchored, one H id per base, no CCN course on the base. Cluster rules become split-candidate columns. Supersedes d-honors-narrow-positive-rule-s654.',array['commons','honors','decision'],'proposed','S654 checkpoint; docs/session_655_handoff.md and the lane files',null,null,'SkyWhimbrel (S654)',date '2026-11-15'),
('d-one-spend-meter-s654','decision','One spend meter prices every paid model call','S654 conductor, #3330: kb/_spend_meter.py prices usage and holds the $40 stop for the pilot, the college workflow and the second reader: reserve before a call, settle after under one lock; the larger reading when usage is ambiguous; a sent call with no usage settles at worst case; a call that never reached the model at $0. Why: COBIx''s zero-priced xAI finding and 13 more were one fault.',array['program-requirements','cost','governance','decision'],'proposed','S654 checkpoint; docs/session_655_handoff.md and the lane files',null,null,'SkyWhimbrel (S654)',date '2026-11-15'),
('d-merge-stack-tops-s654','decision','A stacked PR pair merges as one squash through its top','S654 conductor: a strictly stacked pair merges as one squash through its top branch (#3330 carries #3327; #3326 carries #3323) and the lower PR closes with a pointer: one CI cycle instead of two. Recorded in docs/reference/conductor_mode.md.',array['conductor','branch-policy','decision'],'proposed','S654 checkpoint; docs/session_655_handoff.md and the lane files',null,null,'SkyWhimbrel (S654)',date '2026-11-15'),
('d-rescore-wave-one-branch-s654','decision','Six prefix-alias rescores merged as one wave','S654 conductor: the six prefix-alias rescore PRs merged as one wave branch (#3345 c7b80e95; #3305, #3317 to #3321 closed with pointers). #3305''s display build ae03886f128e was built and never applied, so it was left out: one display build covers all six after the course-id rescore. Statewide passing 15,840 to 15,856 of 22,335.',array['program-requirements','rescore','decision'],'proposed','S654 checkpoint; docs/session_655_handoff.md and the lane files',null,null,'SkyWhimbrel (S654)',date '2026-11-15'),
('d-cdc-held-means-not-shared-s654','decision','CDC dictionary: held means left out of an outside share','S654 conductor, #3326: in the CDC dictionary held means left out of an outside share; the public site serves COBI''s status files, so held never says not published. Coordinator and Counselor routing contacts are public; other staff roles held. COMIS CB course elements are public as the CO course file publishes them. The COMIS Data Mart integration reads in progress (the file came by hand, #3239).',array['commons','college-data-collection','privacy','decision'],'proposed','S654 checkpoint; docs/session_655_handoff.md and the lane files',null,null,'SkyWhimbrel (S654)',date '2026-11-15'),
('d-ge-control-number-needs-title-s654','decision','A GE page''s control number needs its program''s title check','S654 conductor, #3324 (3ec83566): a printed five-digit number names a GE-pattern page''s owner only when it is a listed program''s control number and that program''s title check does not refuse it. The owner is cached per page and the counts pinned to a fixture. Extends d-ge-page-one-owner-s653.',array['program-requirements','ge-pattern','decision'],'proposed','S654 checkpoint; docs/session_655_handoff.md and the lane files',null,null,'SkyWhimbrel (S654)',date '2026-11-15'),
('d-step11-runs-2026-11-15','decision','Step 11''s runs for UTC 2026-11-15','S654 conductor: step 11 for UTC 2026-11-15 is Allan Hancock''s 12-page trial on #3284 (commit 63a449b7) and Santa Ana''s objectives reread on #3344 (claude/slo-objectives-sac, commit 3ab3fef7), both pushed 02:09Z; results unread at the checkpoint. Read each with scripts/next_slo_colleges.py --all on its branch.',array['course-outcomes','step-11','decision'],'proposed','S654 checkpoint; docs/session_655_handoff.md and the lane files',null,null,'SkyWhimbrel (S654)',date '2026-11-15'),
('ppm-three-not-cccs-sam-s654','fact','Sam: the three unfiled Pathways Mapper members were not CCCs','Sam, Open Asks Sheet 198 card 11, 2026-11-14: "I think the 3 were not cccs so no need to worry about it. You can check to ppm website for active cccs to confirm". programmapper.org is outside the cloud session''s network, so the site was not read; his 2026-10-21 remark in kb/supabase_program_source_ppm_hosts_s444.sql says the same. The builder comment quotes him (#3326).',array['commons','college-data-collection','ppm','fact'],'verified','Sam, Open Asks Sheet 198 card 11 (verbatim)','Sam Lee',now(),'SkyWhimbrel (S654)',date '2026-11-15'),
('cobix-3299-spot-check-13-of-14-s654','fact','COBIx''s spot-check of the prefix-alias rescores: 13 of 14','COBIx, #3299 comment 6885498680, 22:54Z 2026-11-14, "findings, not an approval": 13 of 14 records look right as alias passes; Norco 36661 and Riverside City 43897 pass by the Sheet 120 card 1 meets reading; Skyline''s 23 empty-heading pages stay found with a named-course minimum before extraction (the conductor sets the number; not yet set).',array['program-requirements','cobix','rescore','fact'],'proposed','COBIx, #3299 comment 6885498680',null,null,'SkyWhimbrel (S654)',date '2026-11-15'),
('p-worker-type-always-makes-a-worktree-s654','pitfall','The worker agent type always makes a worktree','S654: the worker agent type always creates a worktree, so a fourth worker cannot be a worker at the three-checkout ceiling. A general-purpose agent told to read .claude/agents/worker.md and work in the main checkout did the CDC fixes and the rescore wave at no extra disk (8.4 GB free with three worktrees).',array['conductor','agents','disk','pitfall'],'proposed','S654 checkpoint; docs/session_655_handoff.md and the lane files',null,null,'SkyWhimbrel (S654)',date '2026-11-15'),
('p-api-522-kills-workers-s654','pitfall','An API 522 can end workers mid-task','S654: between 02:28Z and 02:33Z 2026-11-15 an API 522 ended three Opus workers mid-task. Each resumed by one SendMessage with its worktree intact. Tell a long worker to commit and push at each coherent step.',array['conductor','agents','pitfall'],'proposed','S654 checkpoint; docs/session_655_handoff.md and the lane files',null,null,'SkyWhimbrel (S654)',date '2026-11-15'),
('p-context-half-in-70-minutes-s654','pitfall','Conductor context went 17% to 50% in 70 minutes','S654: context went 17% to 50% in 70 minutes, mostly the read-in''s nine reports (about 60,000 tokens) and briefs written inline. What held it after: briefs and finding lists as scratchpad files, capped reports, get_check_runs with perPage 1, one check-in per CI wait.',array['conductor','context','pitfall'],'proposed','S654 checkpoint; docs/session_655_handoff.md and the lane files',null,null,'SkyWhimbrel (S654)',date '2026-11-15'),
('p-conductor-times-from-memory-again-s654','pitfall','Times written from memory ran ahead of the clock again','S654: two times the conductor wrote from memory ran 1 to 6 minutes ahead of the clock (a chat status, a ledger heading). Read date -u in the same command as any time you write.',array['conductor','clock','pitfall'],'proposed','S654 checkpoint; docs/session_655_handoff.md and the lane files',null,null,'SkyWhimbrel (S654)',date '2026-11-15'),
('p-stack-squash-conflicts-s654','pitfall','A stacked PR conflicts after its base squash-merges','S654: a stacked PR still conflicts after its base squash-merges (identical lines changed on both sides of a generated file), so a stacked train cannot skip CI cycles; merging through the stack''s top does (d-merge-stack-tops-s654).',array['conductor','branch-policy','pitfall'],'proposed','S654 checkpoint; docs/session_655_handoff.md and the lane files',null,null,'SkyWhimbrel (S654)',date '2026-11-15'),
('d-control-number-district-format-s654','decision','A district-format control number settles a GE page''s owner','S654 conductor, #3346: a district-format control number (campus letter, six digits, letter) settles a GE-pattern page''s owner anywhere; a bare five-digit run needs agreeing title words. Replaces part of d-ge-control-number-needs-title-s654 for LACCD-format numbers, after the award-led-window rule kept 230 of 314 right answers. Self-recall fixture committed; merge at 314 of 314.',array['program-requirements','ge-pattern','decision'],'proposed','S654 checkpoint; docs/session_655_handoff.md and the lane files',null,null,'SkyWhimbrel (S654)',date '2026-11-15'),
('p-conductor-rule-without-self-recall-s654','pitfall','A matching rule in a brief needs its self-recall test','S654: the conductor wrote a matcher rule into a brief (#3346) without the self-recall test the conductor-brief skill requires; a second reader''s recall run found it refused 84 of 314 right answers (LA Mission 38, LA Trade-Tech 26, LA Valley 20) before the merge. Every brief that states a matching rule asks for recall counts on records whose answer is already held.',array['conductor','matcher','pitfall'],'proposed','S654 checkpoint; docs/session_655_handoff.md and the lane files',null,null,'SkyWhimbrel (S654)',date '2026-11-15')
on conflict (slug) do nothing;
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
select id, 'SkyWhimbrel (S654)', 'create', 'S654 checkpoint (2026-11-15)', to_jsonb(m)
from public.cpl_memory m where m.slug in
  ('d-honors-anchored-rows-s654','d-one-spend-meter-s654','d-merge-stack-tops-s654','d-rescore-wave-one-branch-s654','d-cdc-held-means-not-shared-s654','d-ge-control-number-needs-title-s654','d-step11-runs-2026-11-15','ppm-three-not-cccs-sam-s654','cobix-3299-spot-check-13-of-14-s654','p-worker-type-always-makes-a-worktree-s654','p-api-522-kills-workers-s654','p-context-half-in-70-minutes-s654','p-conductor-times-from-memory-again-s654','p-stack-squash-conflicts-s654','d-control-number-district-format-s654','p-conductor-rule-without-self-recall-s654')
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create');
select m.slug, length(m.summary) as summary_chars, count(l.id) filter (where l.action = 'create') as creates
from public.cpl_memory m left join public.cpl_memory_log l on l.memory_id = m.id
where m.slug in
  ('d-honors-anchored-rows-s654','d-one-spend-meter-s654','d-merge-stack-tops-s654','d-rescore-wave-one-branch-s654','d-cdc-held-means-not-shared-s654','d-ge-control-number-needs-title-s654','d-step11-runs-2026-11-15','ppm-three-not-cccs-sam-s654','cobix-3299-spot-check-13-of-14-s654','p-worker-type-always-makes-a-worktree-s654','p-api-522-kills-workers-s654','p-context-half-in-70-minutes-s654','p-conductor-times-from-memory-again-s654','p-stack-squash-conflicts-s654','d-control-number-district-format-s654','p-conductor-rule-without-self-recall-s654')
group by m.slug, m.summary order by m.slug;
